const dx = Math.cos(a), dy = Math.sin(a), nx = -dy, ny = dx;
const cx = 540, cy = 980, L = 760, gap = 28 + p * 3;
for (let t = -L; t <= L; t += gap) {
const x0 = cx + nx * t - dx * L, y0 = cy + ny * t - dy * L;
let z = '';
const teeth = 14;
for (let i = 0; i < teeth; i++) {
const u = i / teeth, u2 = (i + 1) / teeth;
const sway = Math.sin(u * 5 + p) * 5;
z += `${i ? 'L' : 'M'}${(x0 + dx * L * 2 * u + nx * sway).toFixed(0)} ${(y0 + dy * L * 2 * u + ny * sway).toFixed(0)}L${(x0 + dx * L * 2 * u2 + nx * (sway + 3)).toFixed(0)} ${(y0 + dy * L * 2 * u2 + ny * (sway + 3)).toFixed(0)}`;
}
out += `<path d="${z}" fill="none" stroke="${col}" stroke-width="${(w * (.8 + R() * .45)).toFixed(1)}" opacity="${(op * (.7 + R() * .4)).toFixed(2)}" stroke-linecap="round" stroke-linejoin="round"/>`;
}
}
